[Form]
public class METSalesOrderFinalizationFilterDialog extends FormRun
{
    FormRun             callerFormObject;
    FormDataSource      metSalesOrderShipmentHeaderDS;

}

/// <summary>
///
/// </summary>
public void init()
{
    TransDate       today = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());
    super();

    ShipmentStatus.selection(MetShipmentStatus::Open);
    ShipFromDate.dateValue(today);
    ShipToDate.dateValue(today);

}

/// <summary>
///
/// </summary>
public void clicked()
{
    QueryBuildDataSource        lineQbds;
    callerFormObject = element.args().caller();
    metSalesOrderShipmentHeaderDS = callerFormObject.dataSource(formDataSourceStr(METSalesOrderFinalizationWorkbench, METSalesOrderShipmentLoadHeader)) as FormDataSource;

    if (ShipmentStatus.selection() == enum2int(MetShipmentStatus::Open))
    {
        callerFormObject.design().controlName(formControlStr(METSalesOrderFinalizationWorkbench, ReprintShipment)).enabled(false);
    }
    else 
    {
        callerFormObject.design().controlName(formControlStr(METSalesOrderFinalizationWorkbench, METShipmentUpdateRoutesDialog)).enabled(false);
        callerFormObject.design().controlName(formControlStr(METSalesOrderFinalizationWorkbench, ConfirmShipment)).enabled(false);
    }

    if (shipfromDate.dateValue() == dateNull() || ShipToDate.dateValue() == dateNull())
    {
        throw Error ("Ship dates are mandatory to filter the records.");
    }

    if (shipfromDate.dateValue() > ShipToDate.dateValue())
    {
        throw Error ("Ship from date cannot be later than Ship to date.");
    }

    metSalesOrderShipmentHeaderDS.queryBuildDataSource().clearRange(fieldNum(METSalesOrderShipmentLoadHeader, RecId));

    if (Warehouse.text())
    {
        SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, Warehouse)).value(queryValue(Warehouse.text()));
    }

    if (Route.text())
    {
        SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, Route)).value(queryValue(Route.text()));
    }

    if (CustAccount.text())
    {
        SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, CustAccount)).value(queryValue(CustAccount.text()));
    }

    SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, ConfirmedShipDate)).value(SysQuery::range(ShipFromDate.dateValue(), ShipToDate.dateValue()));

    SysQuery::findOrCreateRange(metSalesOrderShipmentHeaderDS.queryBuildDataSource(), fieldNum(METSalesOrderShipmentLoadHeader, ShipmentStatus)).value(queryValue(ShipmentStatus.selection()));

    lineQbds = metSalesOrderShipmentHeaderDS.queryBuildDataSource().addDataSource(tableNum(METSalesOrderShipmentLoadLines));
    lineQbds.relations(false);
    lineQbds.addLink(fieldNum(METSalesOrderShipmentLoadHeader, ShipmentId), fieldNum(METSalesOrderShipmentLoadLines, ShipmentId));
    lineQbds.joinMode(JoinMode::ExistsJoin);

    metSalesOrderShipmentHeaderDS.executeQuery();
    metSalesOrderShipmentHeaderDS.research(true);

    super();
}
